use serde::{Deserialize, Serialize};

use crate::ToolCall;

/// The originator of a [`Message`] in a conversation turn.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Role {
    /// Instructions that frame the model's behaviour for the whole conversation.
    System,
    /// A turn sent by the end user or caller.
    Human,
    /// A turn generated by the AI model.
    Ai,
    /// A synthetic turn injected by a tool or function-call result.
    Tool,
}

impl std::fmt::Display for Role {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::System => write!(f, "system"),
            Self::Human => write!(f, "human"),
            Self::Ai => write!(f, "ai"),
            Self::Tool => write!(f, "tool"),
        }
    }
}

/// Default upper bound, in decoded bytes, for [`ImageData::validate_default`]
/// (20 MiB — the largest inline image the major providers accept).
pub const DEFAULT_MAX_IMAGE_BYTES: usize = 20 * 1024 * 1024;

/// Longest `http(s)` image URL accepted by [`ImageData::validate`].
pub const MAX_IMAGE_URL_LEN: usize = 8 * 1024;

/// Raw image payload that can be embedded in a message.
///
/// Its [`Debug`] output never includes base64 data, only its length, so
/// logging a message that carries an image does not dump megabytes of
/// (possibly sensitive) pixels into the logs.
///
/// Image data often comes from untrusted sources (uploads, scraped pages);
/// call [`validate`](Self::validate) before forwarding it to a provider.
#[derive(Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case", tag = "type")]
pub enum ImageData {
    /// A publicly accessible image URL.
    Url {
        /// The image URL.
        url: String,
    },
    /// A base64-encoded image with an explicit MIME type.
    Base64 {
        /// MIME type of the image, e.g. `image/png`.
        mime_type: String,
        /// Base64-encoded image bytes.
        data: String,
    },
}

impl std::fmt::Debug for ImageData {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::Url { url } if url.len() > 256 => f
                .debug_struct("Url")
                .field("url", &format_args!("<{} bytes>", url.len()))
                .finish(),
            Self::Url { url } => f.debug_struct("Url").field("url", url).finish(),
            Self::Base64 { mime_type, data } => f
                .debug_struct("Base64")
                .field("mime_type", mime_type)
                .field("data", &format_args!("<{} base64 chars>", data.len()))
                .finish(),
        }
    }
}

/// Why an [`ImageData`] failed [`ImageData::validate`].
#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
#[non_exhaustive]
pub enum ImageError {
    /// The decoded image (or data URL) is larger than the allowed limit.
    #[error("image is {size} bytes, above the {limit}-byte limit")]
    TooLarge {
        /// Size of the payload in bytes (decoded size for base64).
        size: usize,
        /// The limit it exceeded.
        limit: usize,
    },
    /// The MIME type is not a well-formed `image/*` type.
    #[error("invalid image MIME type")]
    InvalidMimeType,
    /// The base64 payload is not valid standard (RFC 4648) base64.
    #[error("image data is not valid base64")]
    InvalidBase64,
    /// The URL is malformed or uses a scheme other than `http`, `https` or
    /// `data:image/…`.
    #[error("unsupported or malformed image URL")]
    InvalidUrl,
}

impl ImageData {
    /// An image referenced by URL.
    ///
    /// # Example
    ///
    /// ```rust
    /// use rune_chain_core::ImageData;
    ///
    /// let img = ImageData::url("https://example.com/cat.png");
    /// assert!(img.validate_default().is_ok());
    /// ```
    pub fn url(url: impl Into<String>) -> Self {
        Self::Url { url: url.into() }
    }

    /// An inline base64-encoded image.
    ///
    /// # Example
    ///
    /// ```rust
    /// use rune_chain_core::ImageData;
    ///
    /// let img = ImageData::base64("image/png", "iVBORw0KGgo=");
    /// assert_eq!(img.decoded_len(), Some(8));
    /// // Debug output shows the size, not the payload.
    /// assert!(!format!("{img:?}").contains("iVBOR"));
    /// ```
    pub fn base64(mime_type: impl Into<String>, data: impl Into<String>) -> Self {
        Self::Base64 {
            mime_type: mime_type.into(),
            data: data.into(),
        }
    }

    /// Decoded size in bytes of a base64 payload, computed from its length
    /// and padding without decoding. `None` for URL images.
    #[must_use]
    pub fn decoded_len(&self) -> Option<usize> {
        match self {
            Self::Url { .. } => None,
            Self::Base64 { data, .. } => {
                let padding = data.bytes().rev().take(2).filter(|&b| b == b'=').count();
                Some((data.len() / 4 * 3).saturating_sub(padding))
            }
        }
    }

    /// [`validate`](Self::validate) with [`DEFAULT_MAX_IMAGE_BYTES`].
    pub fn validate_default(&self) -> Result<(), ImageError> {
        self.validate(DEFAULT_MAX_IMAGE_BYTES)
    }

    /// Check that the image is well-formed and at most `max_bytes` large.
    ///
    /// - base64 images need an `image/<subtype>` MIME type and canonical
    ///   standard base64 (`A–Z a–z 0–9 + /`, `=` padding, length a multiple
    ///   of 4) decoding to at most `max_bytes`;
    /// - URL images must be `http(s)://` (at most [`MAX_IMAGE_URL_LEN`]
    ///   bytes, no whitespace or control characters) or `data:image/…` URLs
    ///   no larger than base64 of `max_bytes` allows.
    ///
    /// The check runs in linear time and allocates nothing.
    ///
    /// # Example
    ///
    /// ```rust
    /// use rune_chain_core::{ImageData, ImageError};
    ///
    /// assert!(ImageData::base64("image/png", "iVBORw0KGgo=").validate(1024).is_ok());
    /// assert_eq!(
    ///     ImageData::base64("text/html", "PGgxPg==").validate(1024),
    ///     Err(ImageError::InvalidMimeType),
    /// );
    /// assert_eq!(
    ///     ImageData::url("file:///etc/passwd").validate(1024),
    ///     Err(ImageError::InvalidUrl),
    /// );
    /// ```
    pub fn validate(&self, max_bytes: usize) -> Result<(), ImageError> {
        match self {
            Self::Url { url } => validate_image_url(url, max_bytes),
            Self::Base64 { mime_type, data } => {
                if !is_image_mime(mime_type) {
                    return Err(ImageError::InvalidMimeType);
                }
                if !is_canonical_base64(data) {
                    return Err(ImageError::InvalidBase64);
                }
                let size = self.decoded_len().unwrap_or(0);
                if size > max_bytes {
                    return Err(ImageError::TooLarge {
                        size,
                        limit: max_bytes,
                    });
                }
                Ok(())
            }
        }
    }
}

/// `image/<subtype>` with RFC 6838 token characters and a sane length.
fn is_image_mime(mime: &str) -> bool {
    mime.len() <= 127
        && mime
            .get(..6)
            .is_some_and(|p| p.eq_ignore_ascii_case("image/"))
        && mime.len() > 6
        && mime[6..]
            .bytes()
            .all(|b| b.is_ascii_alphanumeric() || b"!#$&-^_.+".contains(&b))
}

/// Standard base64 with `=` padding only at the end and a length multiple of 4.
fn is_canonical_base64(data: &str) -> bool {
    let bytes = data.as_bytes();
    if !bytes.len().is_multiple_of(4) {
        return false;
    }
    let body_len = bytes.len()
        - bytes
            .iter()
            .rev()
            .take(2)
            .take_while(|&&b| b == b'=')
            .count();
    bytes[..body_len]
        .iter()
        .all(|&b| b.is_ascii_alphanumeric() || b == b'+' || b == b'/')
}

fn validate_image_url(url: &str, max_bytes: usize) -> Result<(), ImageError> {
    if url
        .bytes()
        .any(|b| b.is_ascii_whitespace() || b.is_ascii_control())
    {
        return Err(ImageError::InvalidUrl);
    }
    let has_prefix = |p: &str| {
        url.get(..p.len())
            .is_some_and(|s| s.eq_ignore_ascii_case(p))
    };
    if has_prefix("data:") {
        let Some((header, payload)) = url[5..].split_once(',') else {
            return Err(ImageError::InvalidUrl);
        };
        let mime = header.split(';').next().unwrap_or_default();
        if !is_image_mime(mime) {
            return Err(ImageError::InvalidMimeType);
        }
        // A base64 payload of `max_bytes` decoded bytes is ~4/3 as long.
        let limit = max_bytes.saturating_add(2) / 3 * 4;
        if payload.len() > limit {
            return Err(ImageError::TooLarge {
                size: payload.len() / 4 * 3,
                limit: max_bytes,
            });
        }
        return Ok(());
    }
    let rest = if has_prefix("https://") {
        &url[8..]
    } else if has_prefix("http://") {
        &url[7..]
    } else {
        return Err(ImageError::InvalidUrl);
    };
    if rest.is_empty() || rest.starts_with('/') || url.len() > MAX_IMAGE_URL_LEN {
        return Err(ImageError::InvalidUrl);
    }
    Ok(())
}

/// A single part within a multi-part message content.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case", tag = "type")]
pub enum ContentPart {
    /// A plain-text fragment.
    Text {
        /// The text.
        text: String,
    },
    /// An image fragment (URL or base64).
    Image {
        /// The image payload.
        image: ImageData,
    },
}

impl ContentPart {
    /// Convenience constructor for a text part.
    pub fn text(text: impl Into<String>) -> Self {
        Self::Text { text: text.into() }
    }

    /// Convenience constructor for an image-URL part.
    pub fn image_url(url: impl Into<String>) -> Self {
        Self::Image {
            image: ImageData::Url { url: url.into() },
        }
    }

    /// Convenience constructor for a base64-encoded image part.
    pub fn image_base64(mime_type: impl Into<String>, data: impl Into<String>) -> Self {
        Self::Image {
            image: ImageData::Base64 {
                mime_type: mime_type.into(),
                data: data.into(),
            },
        }
    }
}

/// The body of a [`Message`]: either plain text or a list of rich content parts.
///
/// `MessageContent` serialises as a JSON string for `Text` and as a JSON array
/// for `Parts`, matching the format expected by `OpenAI`, Anthropic, and Ollama.
///
/// # Constructing
///
/// Plain-text messages work through `From<String>` / `From<&str>`:
/// ```rust
/// use rune_chain_core::MessageContent;
///
/// let c: MessageContent = "hello".into();
/// assert_eq!(c.as_text(), "hello");
/// ```
///
/// Multi-modal messages use [`MessageContent::Parts`]:
/// ```rust
/// use rune_chain_core::{MessageContent, ContentPart};
///
/// let c = MessageContent::Parts(vec![
///     ContentPart::text("What is in this image?"),
///     ContentPart::image_url("https://example.com/cat.jpg"),
/// ]);
/// ```
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(untagged)]
pub enum MessageContent {
    /// Plain UTF-8 text.
    Text(String),
    /// An ordered sequence of rich content parts (text + images).
    Parts(Vec<ContentPart>),
}

impl MessageContent {
    /// Return the text content.
    ///
    /// - For `Text(s)`: borrows `s` directly.
    /// - For `Parts(...)`: returns `""` — use [`text_content`](Self::text_content) to get all text.
    #[must_use]
    pub const fn as_text(&self) -> &str {
        match self {
            Self::Text(s) => s.as_str(),
            Self::Parts(_) => "",
        }
    }

    /// Collect all text fragments into an owned `String`.
    ///
    /// For `Text(s)`: clones `s`.
    /// For `Parts(...)`: joins all `Text` parts with a space.
    #[must_use]
    pub fn text_content(&self) -> String {
        match self {
            Self::Text(s) => s.clone(),
            Self::Parts(parts) => parts
                .iter()
                .filter_map(|p| {
                    if let ContentPart::Text { text } = p {
                        Some(text.as_str())
                    } else {
                        None
                    }
                })
                .collect::<Vec<_>>()
                .join(" "),
        }
    }

    /// Return `true` if this is a plain-text message with no image parts.
    #[must_use]
    pub const fn is_text(&self) -> bool {
        matches!(self, Self::Text(_))
    }

    /// Return `true` if there is no text and no image: an empty string or an
    /// empty part list (or only empty text parts).
    ///
    /// # Example
    ///
    /// ```rust
    /// use rune_chain_core::{ContentPart, MessageContent};
    ///
    /// assert!(MessageContent::from("").is_empty());
    /// assert!(!MessageContent::Parts(vec![ContentPart::image_url("https://x.io/a.png")]).is_empty());
    /// ```
    #[must_use]
    pub fn is_empty(&self) -> bool {
        match self {
            Self::Text(s) => s.is_empty(),
            Self::Parts(parts) => parts
                .iter()
                .all(|p| matches!(p, ContentPart::Text { text } if text.is_empty())),
        }
    }

    /// Iterate over the images in this content (none for `Text`).
    ///
    /// # Example
    ///
    /// ```rust
    /// use rune_chain_core::{ContentPart, MessageContent};
    ///
    /// let c = MessageContent::Parts(vec![
    ///     ContentPart::text("look"),
    ///     ContentPart::image_url("https://example.com/a.png"),
    /// ]);
    /// assert_eq!(c.images().count(), 1);
    /// assert!(c.images().all(|img| img.validate_default().is_ok()));
    /// ```
    pub fn images(&self) -> impl Iterator<Item = &ImageData> {
        let parts: &[ContentPart] = match self {
            Self::Text(_) => &[],
            Self::Parts(parts) => parts,
        };
        parts.iter().filter_map(|p| match p {
            ContentPart::Image { image } => Some(image),
            ContentPart::Text { .. } => None,
        })
    }
}

impl From<Vec<ContentPart>> for MessageContent {
    fn from(parts: Vec<ContentPart>) -> Self {
        Self::Parts(parts)
    }
}

impl From<String> for MessageContent {
    fn from(s: String) -> Self {
        Self::Text(s)
    }
}

impl From<&str> for MessageContent {
    fn from(s: &str) -> Self {
        Self::Text(s.to_string())
    }
}

impl From<&String> for MessageContent {
    fn from(s: &String) -> Self {
        Self::Text(s.clone())
    }
}

impl std::fmt::Display for MessageContent {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}", self.text_content())
    }
}

impl PartialEq<str> for MessageContent {
    fn eq(&self, other: &str) -> bool {
        self.as_text() == other
    }
}

impl PartialEq<&str> for MessageContent {
    fn eq(&self, other: &&str) -> bool {
        self.as_text() == *other
    }
}

impl PartialEq<String> for MessageContent {
    fn eq(&self, other: &String) -> bool {
        self.as_text() == other.as_str()
    }
}

/// Reasoning ("thinking") the model produced before its answer.
///
/// Kept apart from the message [`content`](Message::content), so
/// [`Message::text`] and every other text extraction ignore it. Providers
/// that require earlier reasoning to be sent back (Anthropic extended
/// thinking with tool use) read it from [`Message::reasoning`]; the others
/// drop it when building a request.
///
/// `signature` and `redacted` are opaque provider tokens: pass them back
/// unchanged. [`Debug`] shows only their lengths.
///
/// # Example
///
/// ```rust
/// use rune_chain_core::ReasoningBlock;
///
/// let block = ReasoningBlock::new("2 + 2 is 4.").with_signature("EqQBCgIYAhIM");
/// assert_eq!(block.signature.as_deref(), Some("EqQBCgIYAhIM"));
/// assert!(!format!("{block:?}").contains("EqQB"));
/// assert!(ReasoningBlock::redacted("c2VjcmV0").is_redacted());
/// ```
#[derive(Clone, Default, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[non_exhaustive]
pub struct ReasoningBlock {
    /// The readable reasoning text (empty for a redacted block).
    #[serde(default)]
    pub text: String,
    /// Opaque provider signature that authenticates `text` (Anthropic
    /// `thinking.signature`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub signature: Option<String>,
    /// Opaque encrypted reasoning the provider would not show (Anthropic
    /// `redacted_thinking.data`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub redacted: Option<String>,
}

impl std::fmt::Debug for ReasoningBlock {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let len = |s: &Option<String>| s.as_ref().map(String::len);
        f.debug_struct("ReasoningBlock")
            .field("text", &self.text)
            .field("signature_len", &len(&self.signature))
            .field("redacted_len", &len(&self.redacted))
            .finish()
    }
}

impl ReasoningBlock {
    /// A block of readable reasoning text.
    pub fn new(text: impl Into<String>) -> Self {
        Self {
            text: text.into(),
            ..Self::default()
        }
    }

    /// A redacted block carrying only the provider's opaque `data`.
    pub fn redacted(data: impl Into<String>) -> Self {
        Self {
            redacted: Some(data.into()),
            ..Self::default()
        }
    }

    /// Attach the provider's signature (builder style).
    #[must_use]
    pub fn with_signature(mut self, signature: impl Into<String>) -> Self {
        self.signature = Some(signature.into());
        self
    }

    /// `true` for a redacted block.
    #[must_use]
    pub const fn is_redacted(&self) -> bool {
        self.redacted.is_some()
    }
}

/// Join the readable text of `blocks` with blank lines.
pub fn join_reasoning(blocks: &[ReasoningBlock]) -> String {
    blocks
        .iter()
        .filter(|b| !b.text.is_empty())
        .map(|b| b.text.as_str())
        .collect::<Vec<_>>()
        .join("\n\n")
}

/// A single turn in a conversation, carrying a [`Role`], rich [`MessageContent`],
/// and optional tool-call metadata for function-calling workflows.
///
/// The struct is `#[non_exhaustive]`: build it with [`new`](Self::new), the
/// role shorthands and the `with_*` builders.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[non_exhaustive]
pub struct Message {
    /// Who produced this message.
    pub role: Role,
    /// The message body — plain text or multi-modal parts.
    pub content: MessageContent,
    /// Tool calls the model wants to make (populated on [`Role::Ai`] turns when
    /// the model requests native function calling).
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub tool_calls: Vec<ToolCall>,
    /// The call ID this result belongs to (populated on [`Role::Tool`] turns).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub tool_call_id: Option<String>,
    /// Reasoning the model produced before this [`Role::Ai`] turn. Not part
    /// of [`text`](Self::text).
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub reasoning: Vec<ReasoningBlock>,
    /// Optional stable id, set by the application. Providers ignore it;
    /// history reducers use it to replace a message instead of adding a
    /// second copy.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub id: Option<String>,
}

impl Message {
    /// Create a new [`Message`] with an explicit role and content.
    ///
    /// # Example
    ///
    /// ```rust
    /// use rune_chain_core::{Message, Role};
    ///
    /// let msg = Message::new(Role::Human, "Hello!");
    /// assert_eq!(msg.role, Role::Human);
    /// assert_eq!(msg.content.as_text(), "Hello!");
    /// ```
    pub fn new(role: Role, content: impl Into<MessageContent>) -> Self {
        Self {
            role,
            content: content.into(),
            tool_calls: Vec::new(),
            tool_call_id: None,
            reasoning: Vec::new(),
            id: None,
        }
    }

    /// Shorthand for a [`Role::System`] message.
    pub fn system(content: impl Into<MessageContent>) -> Self {
        Self::new(Role::System, content)
    }

    /// Shorthand for a [`Role::Human`] message.
    pub fn human(content: impl Into<MessageContent>) -> Self {
        Self::new(Role::Human, content)
    }

    /// Shorthand for a [`Role::Ai`] message.
    pub fn ai(content: impl Into<MessageContent>) -> Self {
        Self::new(Role::Ai, content)
    }

    /// Create an AI message that carries pending tool calls.
    ///
    /// Used internally by function-calling agents to represent the model's
    /// "I want to call these tools" turn before observations are appended.
    ///
    /// # Example
    ///
    /// ```rust
    /// use rune_chain_core::{Message, ToolCall};
    ///
    /// let msg = Message::ai_with_tool_calls(
    ///     "",
    ///     vec![ToolCall::new("call_1", "upper_case", r#"{"input":"hello"}"#)],
    /// );
    /// assert_eq!(msg.tool_calls.len(), 1);
    /// ```
    pub fn ai_with_tool_calls(
        content: impl Into<MessageContent>,
        tool_calls: Vec<ToolCall>,
    ) -> Self {
        Self {
            role: Role::Ai,
            content: content.into(),
            tool_calls,
            tool_call_id: None,
            reasoning: Vec::new(),
            id: None,
        }
    }

    /// Create a tool-result message to feed back an observation from a tool call.
    ///
    /// # Example
    ///
    /// ```rust
    /// use rune_chain_core::Message;
    ///
    /// let msg = Message::tool_result("call_1", "HELLO");
    /// ```
    pub fn tool_result(call_id: impl Into<String>, content: impl Into<MessageContent>) -> Self {
        Self {
            role: Role::Tool,
            content: content.into(),
            tool_calls: Vec::new(),
            tool_call_id: Some(call_id.into()),
            reasoning: Vec::new(),
            id: None,
        }
    }

    /// Shorthand for a [`Role::Human`] message carrying text plus one image.
    ///
    /// # Example
    ///
    /// ```rust
    /// use rune_chain_core::{ImageData, Message};
    ///
    /// let msg = Message::human_with_image(
    ///     "What is in this picture?",
    ///     ImageData::url("https://example.com/cat.jpg"),
    /// );
    /// assert_eq!(msg.text(), "What is in this picture?");
    /// assert_eq!(msg.content.images().count(), 1);
    /// ```
    pub fn human_with_image(text: impl Into<String>, image: ImageData) -> Self {
        Self::human(MessageContent::Parts(vec![
            ContentPart::text(text),
            ContentPart::Image { image },
        ]))
    }

    /// All text in this message (see [`MessageContent::text_content`]).
    ///
    /// # Example
    ///
    /// ```rust
    /// use rune_chain_core::Message;
    ///
    /// assert_eq!(Message::ai("4").text(), "4");
    /// ```
    #[must_use]
    pub fn text(&self) -> String {
        self.content.text_content()
    }

    /// Return `true` if this is an AI turn requesting tool calls.
    ///
    /// # Example
    ///
    /// ```rust
    /// use rune_chain_core::{Message, ToolCall};
    ///
    /// assert!(!Message::ai("done").has_tool_calls());
    /// let call = ToolCall::new("c1", "echo", "{}");
    /// assert!(Message::ai_with_tool_calls("", vec![call]).has_tool_calls());
    /// ```
    #[must_use]
    pub const fn has_tool_calls(&self) -> bool {
        !self.tool_calls.is_empty()
    }

    /// Attach reasoning blocks (builder style).
    ///
    /// # Example
    ///
    /// ```rust
    /// use rune_chain_core::{Message, ReasoningBlock};
    ///
    /// let msg = Message::ai("4").with_reasoning(vec![ReasoningBlock::new("2 + 2 = 4")]);
    /// assert_eq!(msg.text(), "4");
    /// assert_eq!(msg.reasoning_text(), "2 + 2 = 4");
    /// ```
    #[must_use]
    pub fn with_reasoning(mut self, reasoning: Vec<ReasoningBlock>) -> Self {
        self.reasoning = reasoning;
        self
    }

    /// Attach tool calls (builder style).
    #[must_use]
    pub fn with_tool_calls(mut self, tool_calls: Vec<ToolCall>) -> Self {
        self.tool_calls = tool_calls;
        self
    }

    /// Set the tool-call ID this message answers (builder style).
    #[must_use]
    pub fn with_tool_call_id(mut self, call_id: impl Into<String>) -> Self {
        self.tool_call_id = Some(call_id.into());
        self
    }

    /// Set the message id (builder style).
    ///
    /// ```rust
    /// use rune_chain_core::Message;
    ///
    /// let msg = Message::human("hi").with_id("m1");
    /// assert_eq!(msg.id.as_deref(), Some("m1"));
    /// ```
    #[must_use]
    pub fn with_id(mut self, id: impl Into<String>) -> Self {
        self.id = Some(id.into());
        self
    }

    /// All readable reasoning text, blocks joined with a blank line.
    #[must_use]
    pub fn reasoning_text(&self) -> String {
        join_reasoning(&self.reasoning)
    }
}
